import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CreateDimensionDto, overageAllowedEnum, TierDto } from './create-dimension.dto.js';

@ValidatorConstraint({ name: 'EntitlementMustBeSetRule', async: false })
@Injectable()
export class EntitlementMustBeSetRule implements ValidatorConstraintInterface {
    validate(overageAllowed: overageAllowedEnum, args: ValidationArguments) {
        const entitlement = (args.object as CreateDimensionDto).usageEntitlement;
        if (overageAllowed === undefined) {
            return true;
        }
        if (overageAllowedEnum.false === overageAllowed && entitlement !== undefined) {
            return true;
        }
        return entitlement !== 'inf' && overageAllowed === overageAllowedEnum.true && entitlement !== undefined;
    }

    defaultMessage() {
        return 'Only entitlement dimension accepts overageAllowed property. Entitlment cannot be inf with overage set to true.';
    }
}

export function EntitlementMustBeSet(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'OverageAllowed',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: EntitlementMustBeSetRule,
        });
    };
}

@ValidatorConstraint({ name: 'EntitlementCanbeInf', async: false })
@Injectable()
export class EntitlementCanbeInfRule implements ValidatorConstraintInterface {
    validate(usageEntitlement?: number | 'inf') {
        if (usageEntitlement === undefined) {
            return true;
        }
        if (usageEntitlement === 'inf') {
            return true;
        }
        if (Number.isInteger(usageEntitlement)) {
            return true;
        }
        return false;
    }

    defaultMessage() {
        return 'Entitlement can be either a number or the string "inf".';
    }
}

export function EntitlementCanbeInf(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'EntitlementCanbeInfRule',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: EntitlementCanbeInfRule,
        });
    };
}

@ValidatorConstraint({ name: 'ShouldSetConsumptionPrice', async: false })
@Injectable()
export class ShouldSetConsumptionPriceRule implements ValidatorConstraintInterface {
    validate(consumptionPrice: string, args: ValidationArguments) {
        const obj = args.object as CreateDimensionDto;
        const entitlement = obj?.usageEntitlement;
        const overageAllowed = obj?.overageAllowed;
        const tiers = obj?.tiers;

        if (tiers && tiers.length > 0) {
            return consumptionPrice === undefined || consumptionPrice === null;
        }

        if (entitlement === undefined || entitlement === null) {
            if (
                consumptionPrice &&
                typeof consumptionPrice === 'string' &&
                !isNaN(consumptionPrice) &&
                !isNaN(parseFloat(consumptionPrice))
            ) {
                return true;
            } else {
                return false;
            }
        }
        if (entitlement !== undefined && entitlement !== null && overageAllowed === overageAllowedEnum.true) {
            if (
                consumptionPrice &&
                typeof consumptionPrice === 'string' &&
                !isNaN(consumptionPrice) &&
                !isNaN(parseFloat(consumptionPrice))
            ) {
                return true;
            } else {
                return false;
            }
        } else if (
            ((overageAllowed === overageAllowedEnum.false || overageAllowed === null) && entitlement !== undefined) ||
            entitlement !== null
        ) {
            if (consumptionPrice) {
                return false;
            } else {
                return true;
            }
        } else {
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        const obj = args.object as CreateDimensionDto;
        const tiers = obj?.tiers;
        if (tiers && tiers.length > 0) {
            return 'Consumption price should not be set when tiers are defined. Tiers define their own unit prices.';
        }
        return `Consumption price should be set as a numeric string if overage is allowed and usage entitlement is set. If there is no entitlement consumption price should also be set. If there is an entitlement and overage is not allowed, consumption price should not be set. Value: ${args.object?.consumptionPrice} is incorrect given: overageAllowed: ${args.object?.overageAllowed} and usageEntitlement: ${args.object?.usageEntitlement}`;
    }
}

export function ShouldSetConsumptionPrice(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ShouldSetConsumptionPrice',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ShouldSetConsumptionPriceRule,
        });
    };
}

@ValidatorConstraint({ name: 'TiersValidation', async: false })
@Injectable()
export class TiersValidationRule implements ValidatorConstraintInterface {
    validate(tiers: TierDto[], args: ValidationArguments) {
        const obj = args.object as CreateDimensionDto;
        if (!tiers || tiers.length === 0) {
            return true;
        }

        const hasEntitlement = obj.usageEntitlement !== undefined && obj.usageEntitlement !== null;
        const hasConsumptionPrice = obj.consumptionPrice !== undefined && obj.consumptionPrice !== null;
        const hasOverageAllowedTrue = obj.overageAllowed === overageAllowedEnum.true;

        if (hasEntitlement || hasConsumptionPrice || hasOverageAllowedTrue) {
            return false;
        }

        const usageIncrement = parseInt(obj.usageIncrement, 10);
        if (isNaN(usageIncrement)) {
            return false;
        }

        let prevUpperBound: number | 'inf' = 0;
        let prevTierPosition = 0;

        for (let i = 0; i < tiers.length; i++) {
            const tier = tiers[i];
            const tierPosition = parseInt(tier.tierPosition, 10);
            if (isNaN(tierPosition)) {
                return false;
            }
            if (tierPosition !== i + 1) {
                return false;
            }
            if (tierPosition <= prevTierPosition) {
                return false;
            }
            prevTierPosition = tierPosition;

            const upperBound = tier.upperBound;
            let upperBoundNum: number | 'inf';
            if (upperBound === 'inf') {
                upperBoundNum = 'inf';
            } else {
                upperBoundNum = parseFloat(upperBound);
                if (isNaN(upperBoundNum)) {
                    return false;
                }
            }

            if (i > 0) {
                if (prevUpperBound === 'inf') {
                    return false;
                }
                if (typeof upperBoundNum === 'number' && upperBoundNum <= prevUpperBound) {
                    return false;
                }
            }

            if (upperBoundNum !== 'inf') {
                if (upperBoundNum % usageIncrement !== 0) {
                    return false;
                }
            } else if (i !== tiers.length - 1) {
                return false;
            }

            if (i > 0 && (!tier.unitPrice || tier.unitPrice.trim() === '')) {
                return false;
            }

            if (tier.unitPrice) {
                const price = parseFloat(tier.unitPrice);
                if (isNaN(price)) {
                    return false;
                }
            }

            prevUpperBound = upperBoundNum;
        }

        return true;
    }

    defaultMessage(args: ValidationArguments) {
        const obj = args.object as CreateDimensionDto;
        const tiers = obj?.tiers;
        if (!tiers || tiers.length === 0) {
            return '';
        }
        return 'Tiers must be mutually exclusive with usageEntitlement, consumptionPrice, and overageAllowed: true. Tier positions must be sequential starting from 1. Upper bounds must increase, align to usageIncrement, and only the last tier may be "inf". All tiers after the first must have a unitPrice.';
    }
}

export function TiersValidation(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'TiersValidation',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TiersValidationRule,
        });
    };
}

