@ValidatorConstraint({ name: 'ShouldSetConsumptionPrice', async: false })
@Injectable()
export class ShouldSetConsumptionPriceRule implements ValidatorConstraintInterface {
    validate(consumptionPrice: string, args: ValidationArguments) {
        const obj = args.object as CreateDimensionDto;
        const entitlement = obj?.usageEntitlement;
        const overageAllowed = obj?.overageAllowed;
        const tiers = obj?.tiers;

        if (tiers && tiers.length > 0) {
            return consumptionPrice === undefined || consumptionPrice === null;
        }

        if (entitlement === undefined || entitlement === null) {
            if (
                consumptionPrice &&
                typeof consumptionPrice === 'string' &&
                !isNaN(Number(consumptionPrice)) &&
                !isNaN(parseFloat(consumptionPrice))
            ) {
                return true;
            } else {
                return false;
            }
        }
        if (entitlement !== undefined && entitlement !== null && overageAllowed === overageAllowedEnum.true) {
            if (
                consumptionPrice &&
                typeof consumptionPrice === 'string' &&
                !isNaN(Number(consumptionPrice)) &&
                !isNaN(parseFloat(consumptionPrice))
            ) {
                return true;
            } else {
                return false;
            }
        } else if (
            ((overageAllowed === overageAllowedEnum.false || overageAllowed === null) && entitlement !== undefined) ||
            entitlement !== null
        ) {
            if (consumptionPrice) {
                return false;
            } else {
                return true;
            }
        } else {
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        const obj = args.object as CreateDimensionDto;
        const tiers = obj?.tiers;
        if (tiers && tiers.length > 0) {
            return 'Consumption price should not be set when tiers are defined. Tiers define their own unit prices.';
        }
        return `Consumption price should be set as a numeric string if overage is allowed and usage entitlement is set. If there is no entitlement consumption price should also be set. If there is an entitlement and overage is not allowed, consumption price should not be set. Value: ${obj?.consumptionPrice} is incorrect given: overageAllowed: ${obj?.overageAllowed} and usageEntitlement: ${obj?.usageEntitlement}`;
    }
}

